void uart\_set\_mac\_address(uart\_joycon\_t \*joycon)
{
 if (!joycon->address\_stored)
 {
 joycon->address[0] = joycon->rx\_buf[33];
 joycon->address[1] = joycon->rx\_buf[32];
 joycon->address[2] = joycon->rx\_buf[31];
 joycon->address[3] = joycon->rx\_buf[30];
 joycon->address[4] = joycon->rx\_buf[29];
 joycon->address[5] = joycon->rx\_buf[28];
 printf("MAC address: ");
 printf\_hexdump(joycon->address, 6);
 joycon->address\_stored = 1;
 }
}

void uart\_store\_link\_key(uart\_joycon\_t \*joycon)
{
 if (!joycon->key\_stored)
 {
 uint8\_t i;
 uint8\_t link\_key[16];
 for (i = 0; i < 16; i++)
 link\_key[i] = joycon->rx\_buf[43 - i] ^ 0xAA; // Read link key little-endian, XOR each byte with 0xAA
 printf("Link key: ");
 printf\_hexdump(link\_key, 16);
 gap\_store\_link\_key\_for\_bd\_addr(joycon->address, link\_key, LOCAL\_UNIT\_KEY);
 joycon->key\_stored = 1;
 }
}

void uart\_set\_cal\_imu(uart\_joycon\_t \*joycon)
{
 joycon->accel\_x\_offset = (joycon->rx\_buf[33] << 8) | joycon->rx\_buf[32];
 joycon->accel\_y\_offset = (joycon->rx\_buf[35] << 8) | joycon->rx\_buf[34];
 joycon->accel\_z\_offset = (joycon->rx\_buf[37] << 8) | joycon->rx\_buf[36];
 joycon->gyro\_x\_offset = (joycon->rx\_buf[45] << 8) | joycon->rx\_buf[44];
 joycon->gyro\_y\_offset = (joycon->rx\_buf[47] << 8) | joycon->rx\_buf[46];
 joycon->gyro\_z\_offset = (joycon->rx\_buf[49] << 8) | joycon->rx\_buf[48];
 printf("Accel X offset: %d\n", joycon->accel\_x\_offset);
 printf("Accel Y offset: %d\n", joycon->accel\_y\_offset);
 printf("Accel Z offset: %d\n", joycon->accel\_z\_offset);
 printf("Gyro X offset: %d\n", joycon->gyro\_x\_offset);
 printf("Gyro Y offset: %d\n", joycon->gyro\_y\_offset);
 printf("Gyro Z offset: %d\n", joycon->gyro\_z\_offset);
}

void uart\_set\_cal\_joy(uart\_joycon\_t \*joycon)
{
 switch (joycon->type)
 {
 case UART\_JOYCON\_L:
 joycon->joy\_x\_center = ((joycon->rx\_buf[36] << 8) & 0xF00) | joycon->rx\_buf[35];
 joycon->joy\_y\_center = (joycon->rx\_buf[37] << 4) | (joycon->rx\_buf[36] >> 4);
 joycon->joy\_x\_min = joycon->joy\_x\_center - (((joycon->rx\_buf[39] << 8) & 0xF00) | joycon->rx\_buf[38]);
 joycon->joy\_x\_max = joycon->joy\_x\_center + (((joycon->rx\_buf[33] << 8) & 0xF00) | joycon->rx\_buf[32]);
 joycon->joy\_y\_min = joycon->joy\_y\_center - ((joycon->rx\_buf[40] << 4) | (joycon->rx\_buf[39] >> 4));
 joycon->joy\_y\_max = joycon->joy\_y\_center + ((joycon->rx\_buf[34] << 4) | (joycon->rx\_buf[33] >> 4));
 break;
 case UART\_JOYCON\_R:
 joycon->joy\_x\_center = ((joycon->rx\_buf[33] << 8) & 0xF00) | joycon->rx\_buf[32];
 joycon->joy\_y\_center = (joycon->rx\_buf[34] << 4) | (joycon->rx\_buf[33] >> 4);
 joycon->joy\_x\_min = joycon->joy\_x\_center - (((joycon->rx\_buf[36] << 8) & 0xF00) | joycon->rx\_buf[35]);
 joycon->joy\_x\_max = joycon->joy\_x\_center + (((joycon->rx\_buf[39] << 8) & 0xF00) | joycon->rx\_buf[38]);
 joycon->joy\_y\_min = joycon->joy\_y\_center - ((joycon->rx\_buf[37] << 4) | (joycon->rx\_buf[38] >> 4));
 joycon->joy\_y\_max = joycon->joy\_y\_center + ((joycon->rx\_buf[40] << 4) | (joycon->rx\_buf[39] >> 4));
 break;
 }
 printf("Joystick X center: %d\n", joycon->joy\_x\_center);
 printf("Joystick Y center: %d\n", joycon->joy\_y\_center);
 printf("Joystick X min: %d\n", joycon->joy\_x\_min);
 printf("Joystick X max: %d\n", joycon->joy\_x\_max);
 printf("Joystick Y min: %d\n", joycon->joy\_y\_min);
 printf("Joystick Y max: %d\n", joycon->joy\_y\_max);
}

void reset\_joycon(uart\_joycon\_t \*joycon)
{
 memset(joycon->address, 0, 6);
 joycon->address\_stored = 0;
 joycon->key\_stored = 0;

 memset(joycon->rx\_buf, 0, 256);
 joycon->handshake\_pos = 0;
 joycon->chars\_remaining = 0;
 joycon->message\_started = 0;
 joycon->message\_received = 0;
 joycon->message\_len = 0;
 joycon->command\_queued = 0;
 joycon->baud\_switch\_queued = 0;
 joycon->connected = 0;
 joycon->connect\_timer = 0;
 joycon->data\_ready = 0;

 joycon->joy\_x\_max = 0;
 joycon->joy\_x\_center = 0;
 joycon->joy\_x\_min = 0;
 joycon->joy\_y\_max = 0;
 joycon->joy\_y\_center = 0;
 joycon->joy\_y\_min = 0;
 joycon->accel\_x\_offset = 0;
 joycon->accel\_y\_offset = 0;
 joycon->accel\_z\_offset = 0;
 joycon->gyro\_x\_offset = 0;
 joycon->gyro\_y\_offset = 0;
 joycon->gyro\_z\_offset = 0;
}

void uart\_joycon\_handle(uart\_joycon\_t \*joycon)
{
 if (joycon->connected)
 {
 // this should be different, more like a check read and then get data
 if (joycon->message\_received)
 {
 // Check responses and get data
 if (!memcmp(joycon->rx\_buf + 26, uart\_handshake\_commands[7] + 23, 6))
 uart\_set\_cal\_imu(joycon);
 if (!memcmp(joycon->rx\_buf + 26, uart\_handshake\_commands[8] + 23, 6) && joycon->type == UART\_JOYCON\_L)
 uart\_set\_cal\_joy(joycon);
 if (!memcmp(joycon->rx\_buf + 26, uart\_handshake\_commands[9] + 23, 6) && joycon->type == UART\_JOYCON\_R)
 uart\_set\_cal\_joy(joycon);
 if (!memcmp(joycon->rx\_buf + 26, uart\_handshake\_commands[10] + 23, 2))
 uart\_set\_mac\_address(joycon);
 if (!memcmp(joycon->rx\_buf + 26, uart\_handshake\_commands[11] + 23, 2))
 uart\_store\_link\_key(joycon);

 if (!memcmp(joycon->rx\_buf, uart\_status\_response\_header, 8))
 joycon->data\_ready = 1;
 else
 joycon->data\_ready = 0;

 uart\_flush(joycon->uart\_num);
 joycon->message\_received = 0;
 joycon->connect\_timer = app\_timer;
 }
 if (joycon->command\_queued && !gpio\_get\_level(joycon->tx\_en\_pin))
 {
 uart\_joycon\_write\_next\_command(joycon);
 joycon->command\_queued = 0;
 }

 if (joycon->baud\_switch\_queued)
 {
 uart\_set\_baudrate(joycon->uart\_num, 3125000);
 printf("Baud switched to 3.125 Mbps\n");
 joycon->baud\_switch\_queued = 0;
 }

 if (((app\_timer - joycon->connect\_timer) % 200) == 0)
 {
 // Resend last status request
 }

 if ((app\_timer - joycon->connect\_timer > 500) && gpio\_get\_level(joycon->tx\_en\_pin))
 { // If 500ms has passed without communication
 printf("Joy-Con disconnected\n");
 uart\_set\_baudrate(joycon->uart\_num, 1000000);
 reset\_joycon(joycon);
 uart\_flush(joycon->uart\_num);
 joycon->uart\_intr.rxfifo\_full\_thresh = 4;
 uart\_enable\_rx\_intr(joycon->uart\_num);
 }
 }
 else
 {
 if (!gpio\_get\_level(joycon->tx\_en\_pin))
 { // This line goes low in a Joy-Con connection event
 printf("Joy-Con connected\n");
 joycon->connected = 1;
 joycon->command\_queued = 1;
 joycon->connect\_timer = app\_timer; // Store time of connection
 uart\_flush(joycon->uart\_num);
 joycon->uart\_intr.rxfifo\_full\_thresh = 4;
 uart\_enable\_rx\_intr(joycon->uart\_num);
 }
 }
}

